<script setup lang="ts">
import{computed,nextTick,ref,useId}from'vue';import MValueBridge from './MValueBridge.vue';import type{MRateProps}from'./types';import{useReferenceConfig}from'./locale';
const props=withDefaults(defineProps<MRateProps>(),{max:5,step:1,clearable:true});const emit=defineEmits<{ 'update:modelValue':[value:number] }>();const{t}=useReferenceConfig();const id=`ui-rate-${useId()}`,range=ref<HTMLInputElement>(),hover=ref<number|null>(null);const maximum=computed(()=>Number.isInteger(props.max)&&props.max>0&&props.max<=1000?props.max:5);const error=computed(()=>maximum.value!==props.max||!Number.isFinite(props.modelValue)||props.modelValue<0||props.modelValue>props.max||props.modelValue/props.step%1?t('rate.invalid','评分或范围不符合步长。'):'');const display=computed(()=>hover.value??props.modelValue);
function set(value:number){if(!props.disabled&&!props.readonly)emit('update:modelValue',value);void nextTick(()=>{if(range.value)range.value.value=String(props.modelValue);});}
function point(event:PointerEvent|MouseEvent,value:number){if(props.step===1)return value;const box=(event.currentTarget as HTMLElement).getBoundingClientRect(),rtl=getComputedStyle(event.currentTarget as HTMLElement).direction==='rtl';return (rtl?event.clientX>box.left+box.width/2:event.clientX<box.left+box.width/2)?value-.5:value;}
</script>
<template><div class="ui-ri" role="group" :aria-label="label"><label :for="props.id||id" class="ui-ri__label">{{label}}</label><div class="ui-ri__row" @pointerleave="hover=null"><button v-for="star in maximum" :key="star" type="button" class="ui-ri-rate__star" :disabled="disabled||readonly" :aria-label="`${star} / ${maximum}`" @pointermove="hover=point($event,star)" @click="set(clearable&&point($event,star)===modelValue?0:point($event,star))"><span aria-hidden="true" class="ui-ri-rate__empty">★</span><span aria-hidden="true" class="ui-ri-rate__filled" :style="{clipPath:`inset(0 ${100-Math.max(0,Math.min(1,display-star+1))*100}% 0 0)`}">★</span></button><span>{{display}} / {{maximum}} {{texts?.[Math.ceil(display)-1]||''}}</span></div><input :id="props.id||id" ref="range" type="range" min="0" :max="maximum" :step="step" :value="modelValue" :disabled="disabled" :aria-readonly="readonly||undefined" @input="set(Number(($event.target as HTMLInputElement).value))"><button v-if="clearable" type="button" class="ui-ri__button" :disabled="disabled||readonly||modelValue===0" @click="set(0)">{{t('clear','清空')}}</button><MValueBridge v-bind="props" :values="modelValue?[String(modelValue)]:[]" :error="error"/></div></template>
<style scoped>.ui-ri-rate__star{position:relative;display:inline-grid;place-items:center;width:44px;height:44px;min-width:44px;border:0;background:transparent;font:32px/1 serif;cursor:pointer}.ui-ri-rate__empty{color:var(--ui-color-rule)}.ui-ri-rate__filled{position:absolute;color:var(--ui-color-warning)}.ui-ri-rate__star:focus-visible{outline:2px solid var(--ui-color-focus)}@media(forced-colors:active){.ui-ri-rate__empty{color:CanvasText}.ui-ri-rate__filled{color:Highlight}}</style>
